{"tool": "write_file", "args": {"content": """"Verify LIFE-215: every eligible household paid exactly 60 for cycle 2, exactly once."""
import json
import os
import sys

sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))

import eligibility.rules as rules
import eligibility.scoring as scoring


def _callables(mod):
    out = {}
    for n in dir(mod):
        if n.startswith('_'):
            continue
        obj = getattr(mod, n)
        if callable(obj):
            try:
                out[n] = (obj, len(inspect.signature(obj).parameters))
            except (TypeError, ValueError):
                pass
    return out


import inspect


def _pick(mod, names, keywords):
    cands = _callables(mod)
    for n in names:
        if n in cands:
            return cands[n]
    for n, v in cands.items():
        if any(k in n.lower() for k in keywords):
            return v
    return None


def _try(fn, *args):
    if fn is None:
        return None
    obj, nparams = fn
    for k in range(min(nparams, len(args)), 0, -1):
        try:
            return obj(*args[:k])
        except TypeError:
            continue
    try:
        return obj()
    except TypeError:
        return None


elig_fn = _pick(rules, ['is_eligible', 'eligible', 'check_eligibility'], ['eligib']) \
    or _pick(scoring, ['is_eligible', 'eligible', 'compute_score', 'score'], ['eligib', 'score'])

with open('data/registry.json') as f:
    raw = json.load(f)
households = raw['households'] if isinstance(raw, dict) and 'households' in raw else raw

with open('data/ledger.json') as f:
    ledger = json.load(f)
if isinstance(ledger, dict):
    ledger = ledger.get('payments', ledger.get('entries', []))

cycle2 = [e for e in ledger if str(e.get('cycle')) == '2']
print('cycle-2 ledger entries:', len(cycle2))

eligible_ids = set()
for h in households:
    hid = h.get('household_id') or h.get('id') if isinstance(h, dict) else h
    hh = h if isinstance(h, dict) else {'household_id': h}
    r = _try(elig_fn, hh, 2, 60)
    if r is True or (r is not None and not isinstance(r, bool) and bool(r) and r != 0):
        eligible_ids.add(hid)
print('eligible households:', sorted(eligible_ids))

paid = {}
bad_amount = []
for e in cycle2:
    hid = e.get('household_id')
    amt = e.get('amount')
    if amt != 60:
        bad_amount.append((hid, amt))
    paid[hid] = paid.get(hid, 0) + 1

dupes = {h: c for h, c in paid.items() if c > 1}
ineligible_paid = set(paid) - eligible_ids
missing = eligible_ids - set(paid)

print('bad amounts:', bad_amount)
print('duplicate payments:', dupes)
print('ineligible paid:', sorted(ineligible_paid))
print('missing eligible:', sorted(missing))

ok = not bad_amount and not dupes and not ineligible_paid and not missing
print('VERIFY:', 'PASS' if ok else 'FAIL')

# audit trail check
if os.path.exists('data/audit.jsonl'):
    with open('data/audit.jsonl') as f:
        lines = [json.loads(l) for l in f if l.strip()]
    a2 = [l for l in lines if str(l.get('cycle')) == '2' or 'cycle2' in str(l.get('event', ''))]
    print('audit cycle-2 entries:', len(a2))
else:
    print('audit.jsonl missing')
